#!/usr/bin/env python3
"""Apply Gaussian parameter noise to a model and save it without training."""

import argparse
from pathlib import Path

import yaml


def load_config(path):
    """Load the perturbation settings generated by the HPO sweep."""
    with open(path) as handle:
        config = yaml.safe_load(handle)
    if not isinstance(config, dict):
        raise ValueError(f"{path} must contain a mapping")
    return config


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--config", required=True, type=Path)
    args = parser.parse_args()

    import torch
    from transformers import AutoModelForCausalLM, AutoTokenizer

    from trainers.rl_perturb import add_gaussian_parameter_noise

    config = load_config(args.config)
    output_dir = Path(config["output_dir"])
    if output_dir.exists():
        raise FileExistsError(f"refusing to overwrite existing model: {output_dir}")

    dtypes = {"bfloat16": torch.bfloat16, "float32": torch.float32}
    dtype_name = config["torch_dtype"]
    if dtype_name not in dtypes:
        raise ValueError(f"unsupported torch_dtype: {dtype_name}")

    model = AutoModelForCausalLM.from_pretrained(
        config["base_model"],
        torch_dtype=dtypes[dtype_name],
        device_map="auto",
    )
    add_gaussian_parameter_noise(
        model,
        sigma=config["gaussian_sigma"],
        seed=config["gaussian_seed"],
    )

    tokenizer = AutoTokenizer.from_pretrained(config["base_model"])
    model.save_pretrained(output_dir, safe_serialization=True)
    tokenizer.save_pretrained(output_dir)


if __name__ == "__main__":
    main()
